changeSet.sql:
CREATE TABLE otp_codes ( id uuid NOT NULL, tenant_id uuid, branch_id uuid, created_at timestamp(6) with time zone NOT NULL, updated_at timestamp(6) with time zone, created_by varchar(255), updated_by varchar(255), deleted boolean NOT NULL,
user_id uuid NOT NULL, code_hash varchar(255) NOT NULL, purpose varchar(40) NOT NULL, channel varchar(20) NOT NULL, destination varchar(255) NOT NULL, expires_at timestamp(6) with time zone NOT NULL, consumed_at timestamp(6) with time zone, attempt_count integer NOT NULL,
PRIMARY KEY (id) );
COMMENT ON COLUMN otp_codes.code_hash IS 'SHA-256 of the code, never the code itself. SHA-256 rather than BCrypt: codes are short-lived and attempt-limited, so a slow hash buys nothing here.'; COMMENT ON COLUMN otp_codes.destination IS 'Where the code was actually sent, captured at send time — deliberately not re-read from the user record at verify time, in case the address changed in between.'; COMMENT ON COLUMN otp_codes.consumed_at IS 'Set when this code can never be used again: successfully used, or superseded by a newer code. Attempt exhaustion is not recorded here — it is visible as attempt_count reaching the limit.';
-- Only PASSWORD_RESET today. Adding a value here without a code -- path behind it would be a fabrication; extend this CHECK in -- the slice that actually builds the new purpose. ALTER TABLE otp_codes ADD CONSTRAINT chk_otp_codes_purpose CHECK (purpose IN ('PASSWORD_RESET'));
-- All three are legal values; only EMAIL is produced today. The -- column exists so an SMS/WhatsApp implementation needs no -- schema change. ALTER TABLE otp_codes ADD CONSTRAINT chk_otp_codes_channel CHECK (channel IN ('EMAIL', 'SMS', 'WHATSAPP'));
